import { createContext, useContext, useEffect, useState } from "react";
import { useLocalStorage, useMediaQuery } from "@mantine/hooks";

const ThemeContext = createContext({
  colorScheme: "light",
  toggleColorScheme: () => {}
});

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("useTheme must be used within ThemeProvider");
  }
  return context;
};

export const ThemeProvider = ({ children }) => {
  const systemPrefersDark = useMediaQuery("(prefers-color-scheme: dark)");
  const [storedColorScheme, setStoredColorScheme] = useLocalStorage({
    key: "mantine-color-scheme",
    defaultValue: "light",
    getInitialValueInEffect: false
  });

  const [colorScheme, setColorScheme] = useState(storedColorScheme || (systemPrefersDark ? "dark" : "light"));

  useEffect(() => {
    const root = document.documentElement;
    const body = document.body;

    if (colorScheme === "dark") {
      root.setAttribute("data-mantine-color-scheme", "dark");
      body.style.backgroundColor = "#111827";
      body.style.color = "#F9FAFB";
    } else {
      root.setAttribute("data-mantine-color-scheme", "light");
      body.style.backgroundColor = "#FFFFFF";
      body.style.color = "#1F2937";
    }
  }, [colorScheme]);

  const toggleColorScheme = () => {
    const newColorScheme = colorScheme === "dark" ? "light" : "dark";
    setColorScheme(newColorScheme);
    setStoredColorScheme(newColorScheme);
  };

  return (
    <ThemeContext.Provider value={{ colorScheme, toggleColorScheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export default ThemeProvider;

export const smoothScrollTo = (elementId, offset = 80) => {
  const element = document.getElementById(elementId);
  if (element) {
    const elementPosition = element.getBoundingClientRect().top + window.pageYOffset;
    const offsetPosition = elementPosition - offset;

    window.scrollTo({
      top: offsetPosition,
      behavior: "smooth"
    });
  }
};

export const scrollToSection = (href) => {
  const elementId = href.replace("#", "");
  smoothScrollTo(elementId);
};

export const getActiveSection = () => {
  const sections = ["hero", "about", "skills", "experience", "projects", "contact"];
  let activeSection = "hero";

  for (const section of sections) {
    const element = document.getElementById(section);
    if (element) {
      const rect = element.getBoundingClientRect();
      if (rect.top <= 100 && rect.bottom >= 100) {
        activeSection = section;
        break;
      }
    }
  }

  return activeSection;
};

export default smoothScrollTo;

export const formatDate = (dateString) => {
  if (!dateString) return "Present";

  const date = new Date(dateString);
  const months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
  ];

  return `${months[date.getMonth()]} ${date.getFullYear()}`;
};

export const formatDateRange = (startDate, endDate) => {
  const start = formatDate(startDate);
  const end = endDate ? formatDate(endDate) : "Present";
  return `${start} - ${end}`;
};

export default formatDateRange;

export const validateEmail = (email) => {
  if (!email) return false;

  const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;

  return emailRegex.test(email);
};

export const validateContactForm = (formData) => {
  const errors = {};

  if (!formData.name || formData.name.trim().length < 2) {
    errors.name = "Name must be at least 2 characters";
  }

  if (!formData.email || !validateEmail(formData.email)) {
    errors.email = "Please enter a valid email address";
  }

  if (!formData.message || formData.message.trim().length < 10) {
    errors.message = "Message must be at least 10 characters";
  }

  return {
    isValid: Object.keys(errors).length === 0,
    errors
  };
};

export default validateEmail;

import { useState, useEffect } from "react";
import { Box, Group, Text, Burger, Drawer, Stack, Anchor } from "@mantine/core";
import { useMediaQuery } from "@mantine/hooks";
import { smoothScrollTo, getActiveSection } from "../../lib/smoothScroll";
import ThemeToggle from "../common/ThemeToggle";
import { siteContent } from "../../data/siteContent";

const Navbar = () => {
  const [opened, setOpened] = useState(false);
  const [activeSection, setActiveSection] = useState("hero");
  const isMobile = useMediaQuery("(max-width: 768px)");

  useEffect(() => {
    const handleScroll = () => {
      const section = getActiveSection();
      setActiveSection(section);
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll();

    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const handleNavClick = (e, href) => {
    e.preventDefault();
    const elementId = href.replace("#", "");
    smoothScrollTo(elementId);
    setOpened(false);
  };

  const navLinks = siteContent.navigation.map((item) => (
    <Anchor
      key={item.id}
      href={item.href}
      onClick={(e) => handleNavClick(e, item.href)}
      style={{
        color: activeSection === item.id ? "var(--mantine-color-blue-6)" : "inherit",
        fontWeight: activeSection === item.id ? 600 : 400,
        textDecoration: "none",
        transition: "color 0.2s ease"
      }}
    >
      {item.label}
    </Anchor>
  ));

  const mobileNavLinks = siteContent.navigation.map((item) => (
    <Text
      key={item.id}
      component="a"
      href={item.href}
      onClick={(e) => handleNavClick(e, item.href)}
      style={{
        color: activeSection === item.id ? "var(--mantine-color-blue-6)" : "inherit",
        fontWeight: activeSection === item.id ? 600 : 400,
        textDecoration: "none",
        fontSize: "1.25rem",
        padding: "0.75rem 0",
        cursor: "pointer"
      }}
    >
      {item.label}
    </Text>
  ));

  return (
    <>
      <Box
        component="nav"
        style={{
          position: "sticky",
          top: 0,
          zIndex: 100,
          backgroundColor: "var(--mantine-color-body)",
          borderBottom: "1px solid var(--mantine-color-gray-3)",
          padding: "1rem 0"
        }}
      >
        <Group justify="space-between" align="center" style={{ maxWidth: "1320px", margin: "0 auto", padding: "0 1rem" }}>
          <Text
            component="a"
            href="#hero"
            onClick={(e) => handleNavClick(e, "#hero")}
            style={{
              fontSize: "1.5rem",
              fontWeight: 700,
              textDecoration: "none",
              color: "var(--mantine-color-blue-6)",
              cursor: "pointer"
            }}
          >
            {siteContent.personal.name.split(" ")[0]}
          </Text>

          {isMobile ? (
            <Group gap="sm">
              <ThemeToggle />
              <Burger opened={opened} onClick={() => setOpened(!opened)} size="sm" />
            </Group>
          ) : (
            <Group gap="xl">{navLinks}</Group>
          )}
        </Group>
      </Box>

      <Drawer
        opened={opened}
        onClose={() => setOpened(false)}
        title={siteContent.personal.name.split(" ")[0]}
        padding="md"
        size="70%"
        position="right"
      >
        <Stack gap="md">{mobileNavLinks}</Stack>
      </Drawer>
    </>
  );
};

export default Navbar;

