import { useState, useEffect, useRef } from "react";
import { Group, Text, Progress, Box } from "@mantine/core";

const SkillBar = ({ skill, delay = 0 }) => {
  const [animatedValue, setAnimatedValue] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          setTimeout(() => {
            setAnimatedValue(skill.proficiency);
          }, delay);
        }
      },
      { threshold: 0.1 }
    );

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => {
      if (ref.current) {
        observer.unobserve(ref.current);
      }
    };
  }, [skill.proficiency, delay]);

  return (
    <Box ref={ref} style={{ marginBottom: "1rem" }}>
      <Group justify="space-between" style={{ marginBottom: "0.5rem" }}>
        <Text style={{ fontWeight: 500 }}>{skill.name}</Text>
        <Group gap="xs">
          <Text size="sm" color="gray.6">{skill.years}+ years</Text>
          <Text size="sm" weight={600} color="blue.6">{skill.proficiency}%</Text>
        </Group>
      </Group>
      <Progress
        value={animatedValue}
        color="blue"
        size="lg"
        radius="xl"
        animated={isVisible}
        style={{
          transition: "width 0.5s ease-out"
        }}
      />
    </Box>
  );
};

export default SkillBar;

import { Card, Image, Text, Group, Badge, Button, Stack, Box } from "@mantine/core";
import { IconExternalLink, IconBrandGithub } from "@tabler/icons-react";

const ProjectCard = ({ project }) => {
  const handleExternalLink = (url) => {
    if (url) {
      window.open(url, "_blank", "noopener,noreferrer");
    }
  };

  return (
    <Card
      style={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        transition: "transform 0.2s ease, box-shadow 0.2s ease"
      }}
    >
      <Card.Section>
        <Image
          src={project.image}
          alt={project.title}
          height={200}
          style={{
            objectFit: "cover",
            borderTopLeftRadius: "var(--mantine-radius-lg)",
            borderTopRightRadius: "var(--mantine-radius-lg)"
          }}
        />
      </Card.Section>

      <Stack gap="sm" style={{ flex: 1, padding: "1rem" }}>
        <Text style={{ fontWeight: 600, fontSize: "1.25rem" }}>{project.title}</Text>

        <Text size="sm" color="gray.6} lineClamp={3}>
          {project.description}
        </Text>

        <Group gap="xs" style={{ flexWrap: "wrap" }}>
          {project.technologies.map((tech) => (
            <Badge
              key={tech}
              variant="light"
              color="blue"
              size="sm"
            >
              {tech}
            </Badge>
          ))}
        </Group>
      </Stack>

      <Group gap="sm" style={{ padding: "0 1rem 1rem" }}>
        {project.liveUrl && (
          <Button
            leftSection={<IconExternalLink size={16} />}
            variant="filled"
            size="sm"
            onClick={() => handleExternalLink(project.liveUrl)}
          >
            Live Demo
          </Button>
        )}

        {project.githubUrl && (
          <Button
            leftSection={<IconBrandGithub size={16} />}
            variant="outline"
            size="sm"
            onClick={() => handleExternalLink(project.githubUrl)}
          >
            GitHub
          </Button>
        )}
      </Group>
    </Card>
  );
};

export default ProjectCard;

import { Group, ActionIcon } from "@mantine/core";
import { IconBrandLinkedin, IconBrandGithub, IconBrandTwitter, IconMail } from "@tabler/icons-react";

const SocialLinks = ({ links, size = "lg" }) => {
  const iconSize = size === "sm" ? 18 : size === "lg" ? 22 : 20;

  const getIcon = (name) => {
    const iconMap = {
      LinkedIn: IconBrandLinkedin,
      GitHub: IconBrandGithub,
      Twitter: IconBrandTwitter,
      Email: IconMail
    };
    return iconMap[name] || IconMail;
  };

  return (
    <Group gap="sm">
      {links.map((link) => {
        const Icon = getIcon(link.name);
        return (
          <ActionIcon
            key={link.name}
            component="a"
            href={link.url}
            target="_blank"
            rel="noopener noreferrer"
            size={size}
            variant="subtle"
            color="gray.7"
            style={{
              transition: "color 0.2s ease, transform 0.2s ease"
            }}
          >
            <Icon size={iconSize} />
          </ActionIcon>
        );
      })}
    </Group>
  );
};

export default SocialLinks;

import { ActionIcon, useMantineColorScheme } from "@mantine/core";
import { IconSun, IconMoon } from "@tabler/icons-react";
import { useTheme } from "../context/ThemeContext";

const ThemeToggle = ({ size = "lg" }) => {
  const { colorScheme, toggleColorScheme } = useTheme();
  const iconSize = size === "sm" ? 18 : size === "lg" ? 22 : 20;

  return (
    <ActionIcon
      onClick={toggleColorScheme}
      size={size}
      variant="subtle"
      color="gray.7"
      aria-label="Toggle color scheme"
      style={{
        transition: "color 0.2s ease, transform 0.2s ease"
      }}
    >
      {colorScheme === "dark" ? (
        <IconSun size={iconSize} />
      ) : (
        <IconMoon size={iconSize} />
      )}
    </ActionIcon>
  );
};

export default ThemeToggle;

